import React, { useState } from "react";
import "./TopNavBlock.scss";
import { MpaIcon } from "../icon/MpaIcon";
import { SvgMpaIcon } from "../../assets/icons";
import { Link as RouterLink } from "react-router-dom"

type MenuItemType = {
  label: string;
  link?: string;
  menuItems?: MenuItemType[];
  subMenuItems?: MenuItemType[];
  showDivider?: boolean;
  leadingIcon?: keyof typeof SvgMpaIcon | string;
  disabled?: boolean;
};

export interface NavMenuProps {
  id: string;
  navItems: MenuItemType[];
  colour?: "primary" | "secondary" | "tertiary";
  LinkComponent?: React.ComponentType<any>;
  isSingleLevel?: boolean;
  toggleMenu?: () => void;
}

const TopNavBlock: React.FC<NavMenuProps> = ({ id, navItems, colour, LinkComponent, isSingleLevel, toggleMenu }) => {
  const [openItems, setOpenItems] = useState<Set<string>>(new Set());

  const toggleDropdown = (key: string, parentKey?: string) => {
    setOpenItems((prev) => {
      const newOpenItems = new Set(prev);
      if (newOpenItems.has(key)) {
        newOpenItems.delete(key);
      } else {
        if (!parentKey) {
          newOpenItems.clear();
        } else {
          [...newOpenItems].forEach((openKey) => {
            if (openKey.startsWith(parentKey) && openKey !== key) {
              newOpenItems.delete(openKey);
            }
          });
        }
        if (parentKey) {
          newOpenItems.add(parentKey);
        }

        newOpenItems.add(key);
      }
      return newOpenItems;
    });
  };

  const Link = LinkComponent ?? RouterLink

  const renderMenuItem = (item: MenuItemType, index: number, depth: number = 0, parentKey: string = "") => {
    const itemKey = parentKey ? `${parentKey}-${index}` : `${depth}-${index}`;
    const isOpen = openItems.has(itemKey);
    const depthClass = `depth-${depth}`;

    return (
      <div key={itemKey} style={{ paddingTop: ".25em" }}>

        {isSingleLevel
          ? <div>
            {item && (
              <div className="top-nav-menu-item depth-0">
                {item.link && <Link className="menu-item-link" onClick={toggleMenu} to={item.link}>{item.label}</Link>}
              </div>
            )}
          </div>
          : <>
            <div
              tabIndex={0}
              role="button"
              onKeyDown={(e) => {
                if (e.key === "Enter" || e.key === " ") toggleDropdown(itemKey, parentKey);
              }}
              className={`top-nav-menu-item 
              ${colour} 
              ${isOpen ? "top-nav-menu-item-selected" : "top-nav-menu-item-default"} 
              ${item?.disabled ? "disabled" : ""} 
              ${depthClass}`}
              onClick={() => toggleDropdown(itemKey, parentKey)}
            >

              <div className="top-nav-menu-content">
                {item.leadingIcon && (
                  <span className={`top-nav-menu-block-leading-icon ${colour} ${isOpen ? "top-nav-menu-block-selected" : "top-nav-menu-block-default"}`}>
                    <MpaIcon iconName={item.leadingIcon} />
                  </span>
                )}

                {item.link && (
                  <Link to={item.link}>
                    {item.label}
                  </Link>
                )}
                {/* 
            {item.label && item.link ? (
              <Link to={item.link}>
                {item.label}
              </Link>
            ) : item.label ? (
              <span>{item.label}</span>
            ) : null} */}


                {((item.menuItems && item.menuItems.length !== 0) || (item.subMenuItems && item.subMenuItems.length !== 0)) && (
                  <span className={`top-nav-menu-item-chevron-icon ${isOpen ? "rotated" : ""}`}>
                    <MpaIcon iconName={'ChevronDown'} />
                  </span>
                )}
              </div>
            </div>
            {isOpen && item.menuItems && (
              <div className="top-nav-submenu-item">
                {item.menuItems?.map((subItem, subIndex) =>
                  renderMenuItem(subItem, subIndex, depth + 1, itemKey)
                )}
              </div>
            )}

            {isOpen && item.subMenuItems && (
              <div className="top-nav-submenu-item">
                {item.subMenuItems?.map((subItem, subIndex) =>
                  renderSubMenuItem(subItem, subIndex, depth + 1, itemKey)
                )}
              </div>
            )}
          </>
        }
      </div>
    );
  };

  const renderSubMenuItem = (item: MenuItemType, index: number, depth: number = 0, parentKey: string = "") => {
    const itemKey = parentKey ? `${parentKey}-${index}` : `${depth}-${index}`;
    const isOpen = openItems.has(itemKey);
    const depthClass = `depth-${depth}`;

    return (
      <div key={itemKey} style={{ paddingTop: ".25em" }}>
        <div
          tabIndex={0}
          role="button"
          className={`top-nav-menu-item 
            ${colour} 
            ${isOpen ? "top-nav-menu-item-selected" : "top-nav-menu-item-default"} 
            ${item?.disabled ? "disabled" : ""} 
            ${depthClass}`
          }
        >
          <a href={item.link}>
            {item.label}
          </a>
        </div>
      </div>
    );
  };

  return <div id={id} className="top-nav-menu">{navItems.map((item, index) => renderMenuItem(item, index, 0))}</div>;
};

export default TopNavBlock;